INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-mur:baliste-tour', 'attaque_mur', 'Baliste tour', 'Une arbalète géante fixée au sol, tire des carreaux géants capables de percer les meilleures armures. Permet d''infliger des dégâts conséquents contre les machines de guerre ennemies.', '80 dégâts fixes, Ignore les armures, détruit le morceau d''armure touché.', 80, NULL, 2, 'craft', 'Ressources et Craft › Machine de GuerreSiège › AI8:BP10', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-mur:mangonneau', 'attaque_mur', 'Mangonneau', 'Un petit trébuchet sur une tour capable de tirer 8 petits projectiles. Très efficace pour arrêter les machines de guerre.', 'Les rochers infligent 80 points de dégâts.', 80, NULL, 1, 'craft', 'Ressources et Craft › Machine de GuerreSiège › AI5:BP7', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-sol:baliste-sol', 'attaque_sol', 'Baliste sol', 'Une arbalète géante fixée au sol, tire des carreaux géants capables de percer les meilleures armures. Très utile pour harceler les unités distances sur les murs et tours.', '80 dégâts fixes, Ignore les armures, détruit le morceau d''armure touché.', 80, NULL, 1, 'craft', 'Ressources et Craft › Machine de GuerreSiège › A5:AH7', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-sol:beffroi', 'attaque_sol', 'Beffroi', 'Une immense tour montée sur roue capable d''accueillir plusieurs vingtaines de soldats, elle sert à fournir un moyen de montée sur les murailles de l''adversaire. Ses grandes parois de bois épais lui permettent de résister au brûlure et aux projectiles.', 'Permet d''avoir un moyen de montée les murs en toute sécurité.', NULL, NULL, 5, 'craft', 'Ressources et Craft › Machine de GuerreSiège › A17:AH19', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-sol:belier', 'attaque_sol', 'Bélier', 'Une structure montée sur un châssis sur roue et couvert par un toit un bois. Il faut être 6 pour le pousser (3 pour les Terre et Sang). Un énorme tronc amélioré d''une tête de métal au bout qui permet de faire des énormes dégâts contre les structures.', 'Inflige 300 dégâts contre les murs, portes et  armes de sièges bâtiments.', 300, NULL, 2, 'craft', 'Ressources et Craft › Machine de GuerreSiège › A8:AH10', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-sol:couillard', 'attaque_sol', 'Couillard', 'Une version plus petite du trébuchet avec deux contrepoids au lieu d''un seul qui rappelle étrangement des bourses. Moins puissante mais plus rapide à recharger, demande 5 minutes de recharge.', 'Un rocher inflige 100 points de dégâts.', 100, NULL, 4, 'craft', 'Ressources et Craft › Machine de GuerreSiège › A14:AH16', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-sol:goliath', 'attaque_sol', 'Goliath', 'Un Golem géant fait de multiples alliages, il mesure plus de 10 mètres de haut et est considéré comme une abomination parmi les machines de sièges tellement il est puissant. Le fait de l''utiliser est prohibé.', 'Son poing inflige 250 dégâts fixes.', 250, NULL, 6, 'craft', 'Ressources et Craft › Machine de GuerreSiège › A20:AH22', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:attaque-sol:trebuchet', 'attaque_sol', 'Trébuchet', 'Une sorte de fronde géante à contrepoids capable de balancer des projectiles de plus de 100kg. Très utile pour détruire les murs ou bâtiments qui menaceraient le siège. Demande 15 minutes de recharge.', 'Un rocher inflige 200 points de dégâts.', 200, NULL, 3, 'craft', 'Ressources et Craft › Machine de GuerreSiège › A11:AH13', NULL);
INSERT INTO machine_guerre (id, categorie, nom, description, effet, degats, points_de_vie, ordre, origine, source_ref, remarque) VALUES ('ressources/machine-de-guerresiege#machine:defense-sol:mantelet', 'defense_sol', 'Mantelet', 'Un bouclier géant en bois et fer, permet d''installer un grand obstacle capable d''encaisser plusieurs tirs de baliste ou projectiles de mangonneau.', 'Possède 400 points de vie', NULL, 400, 1, 'craft', 'Ressources et Craft › Machine de GuerreSiège › A27:AH29', NULL);
